    font-weight: 600;
    margin-top: 10px;
    font-size: 0.95rem;
    box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}
.st-btn:hover { 
    background: rgba(255,255,255,0.1); 
    border-color: rgba(255,255,255,0.2);
    transform: translateY(-1px);
    box-shadow: 0 6px 12px rgba(0,0,0,0.2);
}
.st-btn:active {
    transform: translateY(1px);
}
.st-btn-s { 
    padding: 6px 16px; 
    border-radius: 20px; 
    background: rgba(255,255,255,0.05); 
    border: 1px solid rgba(255,255,255,0.1); 
    color: var(--dim); 
    cursor: pointer; 
    font-size: 0.8rem; 
    font-weight: 600;
    transition: .2s; 
    display: flex;
    align-items: center;
    gap: 6px;
}
.st-btn-s:hover {
    background: rgba(255,255,255,0.15);
    color: #fff;
    box-shadow: 0 2px 8px rgba(0,0,0,0.2);
}
.st-chk {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 24px;
    height: 24px;
    background: var(--c);
    border-radius: 50%;
    display: grid;
    place-items: center;
    color: #fff;
    box-shadow: 0 4px 10px rgba(0,0,0,0.5);
    z-index: 10;
    animation: popIn 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    font-size: 0.9rem;
}
@keyframes popIn { from { transform: translate(-50%, -50%) scale(0); } to { transform: translate(-50%, -50%) scale(1); } }

.det-c{position:relative;overflow:hidden;min-height:350px}
.det-r{
    display:flex;
    padding:12px;
    border-radius:14px;
    background:var(--slot-outer);
    box-shadow:inset 0 2px 4px rgba(0,0,0,0.2), 0 1px 0 rgba(255,255,255,0.05);
    border:1px solid rgba(255,255,255,0.02);
    width:100%;transition:transform .45s cubic-bezier(0.19, 1, 0.22, 1);position:relative;
    will-change: transform;
}
.det-r::after{content:'';position:absolute;top:0;left:0;width:3px;height:100%;background:var(--c);box-shadow:2px 0 15px var(--c)}

.left-col {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    gap: 12px;
    flex-shrink: 0;
    width: calc(20px + (240px * var(--img-scale, 1)));
    height: 100%;
}

.av-d{
    width:calc(240px * var(--img-scale, 1));height:calc(320px * var(--img-scale, 1));border:3px solid var(--c);border-radius:16px;
    object-fit:cover;cursor:pointer;transition:.3s;
    box-shadow:0 8px 20px rgba(0,0,0,0.6);
    opacity: 0; transition: opacity 0.4s ease;
}


.poet-box-m { display: none; }
.poet-box-pc { display: flex; flex-direction: row-reverse; gap: 8px; margin-left: 10px; align-items: center; justify-content: center; flex-shrink: 0; }

.poet-line {
    font-family: 'Ma Shan Zheng', 'KaiTi', 'STKaiti', cursive;
    color: var(--c);
    font-size: 0.85rem;
    line-height: 1.1;
    text-shadow: 0 0 5px rgba(0,0,0,0.8);
    opacity: 0.9;
    writing-mode: vertical-rl; 
    text-orientation: upright;
    letter-spacing: 2px;
}

.poet-line:first-child { margin-top: -12px; } 
.poet-line:last-child { margin-top: 12px; }  

.nm-d{
    font-family:'Noto Serif SC', 'Songti SC', 'SimSun', serif;font-size:1.25rem;font-weight:700;color:var(--c);
    margin-bottom:8px;text-shadow:0 0 15px var(--c);letter-spacing:1px;line-height: 1;
}

.pv{
    position:fixed;inset:0;display:none;place-items:center;
    background:rgba(0,0,0,0.94);backdrop-filter:blur(14px);z-index:99;animation:f .25s ease-out;
    will-change: opacity;
}
.pv-b{
    background:var(--bg);border-radius:20px;border:1px solid rgba(255,255,255,0.1);
    max-width:90vw;max-height:90vh;box-shadow:0 30px 90px #000;
    display:flex;flex-direction:column;animation:p .3s cubic-bezier(0.19, 1, 0.22, 1);overflow:hidden;
    position: relative;
    will-change: transform, opacity;
}
.pv-n{
    text-align:center;color:#fff;
    padding:10px; font-weight:600;
    font-family:'Noto Serif SC', 'Songti SC', 'SimSun', serif; font-size:0.9rem; letter-spacing:2px;
    border-bottom:1px solid rgba(255,255,255,0.06);text-shadow:0 0 20px var(--c)
}
.pv-i-c{
    flex:1;padding:0;display:flex;justify-content:center;overflow:hidden;background:rgba(0,0,0,0.3);
    position: relative;
}
.pv-img {
    max-width: 100%;
    max-height: 100%;
    width: auto;
    height: auto;
    object-fit: contain;
    transition: transform 0.3s cubic-bezier(0.2,0.8,0.2,1), opacity 0.2s;
    display: block;
    will-change: transform, opacity;
}

.anim{opacity:0;transform:translateY(10px);animation:up .45s cubic-bezier(0.19, 1, 0.22, 1) forwards}
@keyframes f{from{opacity:0}to{opacity:1}} @keyframes p{from{transform:scale(.92);opacity:0}to{transform:scale(1);opacity:1}}
@keyframes up{to{opacity:1;transform:translateY(0)}}

.pv:fullscreen .pv-b, .pv:-webkit-full-screen .pv-b {
    max-width: 100vw; max-height: 100vh; width: 100vw; height: 100vh; border-radius: 0; border: none;
}
.pv:fullscreen .pv-img, .pv:-webkit-full-screen .pv-img {
    max-height: calc(100vh - 40px);
}

@media (max-width: 600px) {
    .poet-box-m {
        display: flex; flex: 1; flex-direction: row-reverse;
        justify-content: center; align-items: center; gap: 6px;
        margin-top: 6px; width: 100%;
    }
    .poet-box-pc { display: none; }

    .w {
        width: 100%;
        border-radius: 0;
        border: none;
        padding: 8px 12px;
    }
    .left-col { width: calc(20px + (140px * var(--img-scale, 1))); gap: 8px; }
    .av-d { width: calc(140px * var(--img-scale, 1)); height: calc(196px * var(--img-scale, 1)); border-width: 2px; border-radius: 12px; }
    .det-c { min-height: 220px; }
    .inf { margin-left: 8px; }
    .poet-line { font-size: 0.75rem; letter-spacing: 1px; }

    .w::before { left: 0; right: 0; }
    .tb {
        padding-bottom: 8px;
        margin-bottom: 8px;
        border-bottom: 1px solid rgba(255,255,255,0.06);
    }
    .tg {
        width: 28px; height: 28px;
        font-size: 0.8rem;
        border-radius: 6px;
    }
    .tit {
        font-size: 1rem;
        text-shadow: 0 0 10px var(--c);
    }

    #st-m .pv-b {
            width: 100% !important;
            height: 100% !important;
            max-width: 100% !important;
            max-height: 100% !important;
            border-radius: 0 !important;
            border: none !important;
            padding: 12px !important;
            background: var(--bg);
