const getStage = (name, val) => {
    val = parseInt(val) || 0;
    if (name === '绛雪') {
        if (val <= 75) return '瑶台冰镜';
        if (val <= 150) return '云破月窥';
        if (val <= 225) return '海棠春醉';
        if (val <= 299) return '玉山倾倒';
        return '欢喜天';
    }
    if (name === '竹夭') {
        if (val <= 75) return '灵窍未开';
        if (val <= 150) return '乍暖还寒';
        if (val <= 225) return '贪欢求索';
        if (val <= 299) return '巴蛇吞象';
        return '摩呼罗';
    }
    return '';
}

