import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// 绛雪阶段计算
const 计算绛雪阶段 = (善业) => {
  if (善业 >= 300) return '欢喜天';
  if (善业 >= 226) return '玉山倾倒';
  if (善业 >= 151) return '海棠春醉';
  if (善业 >= 76) return '云破月窥';
  return '瑶台冰镜';
};

// 竹夭阶段计算
const 计算竹夭阶段 = (善业) => {
  if (善业 >= 300) return '摩呼罗';
  if (善业 >= 226) return '巴蛇吞象';
  if (善业 >= 151) return '贪欢求索';
  if (善业 >= 76) return '乍暖还寒';
  return '灵窍未开';
};

export const Schema = z.object({
  世界: z.object({
    当前时间: z.string().prefault('待初始化'),
    当前地点: z.string().prefault('待初始化'),
  }),

  绛雪: z
    .object({
      善业: z.coerce.number().transform(v => _.clamp(v, 0, 300)).prefault(0),
      阶段: z.string().prefault('瑶台冰镜'),
      自白: z.string().prefault(''),
      衣着: z.string().prefault('待填写'),
      外貌: z.string().prefault('待填写'),
    })
    .transform(data => {
      data.阶段 = 计算绛雪阶段(data.善业);
      return data;
    }),

  竹夭: z
    .object({
      善业: z.coerce.number().transform(v => _.clamp(v, 0, 300)).prefault(0),
      阶段: z.string().prefault('灵窍未开'),
      自白: z.string().prefault(''),
      衣着: z.string().prefault('待填写'),
      外貌: z.string().prefault('待填写'),
    })
    .transform(data => {
      data.阶段 = 计算竹夭阶段(data.善业);
      return data;
    }),

  孟秋娘: z.object({
    衣着: z.string().prefault('待填写'),
    外貌: z.string().prefault('待填写'),
  }),

  慈脂佛母: z.object({
    衣着: z.string().prefault('待填写'),
    外貌: z.string().prefault('待填写'),
  }),
});

$(() => {
  registerMvuSchema(Schema);
});
